head.script:
scwin.screenId = "jldbnf15301";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_otherwise_32", fn: function(){ return (!(((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'))); } }, { id: "c_when_79", fn: function(){ return ((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'); } }, { id: "c_otherwise_84", fn: function(){ return (!(((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":2
        ,"mmenu":9
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf15301' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf15301.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_save_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.save()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15301.btn_save_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15301.btn_close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/company/company.do?method=saveSplitAppl",
        ref: "dma_saveReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf15301.tx_fn_save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/company/company.do?method=saveSplitAppl';
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuNm').getValue()) == 0) {
        await $c.win.alert("한글종목명을 입력하십시오.");
        $c.util.getComponent("ipt_applIsuNm").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuEngNm').getValue()) == 0) {
            await $c.win.alert("영문종목명을 입력하십시오.");
            $c.util.getComponent("ipt_applIsuEngNm").focus();
            return false;
        } else {
            if ($c.util.getComponent('dma_saveReq').get('bndMergeObjTpCd')!== "1" && $c.str.getByteLength($c.util.getComponent('ipt_splitRtoContn').getValue()) == 0) {
                await $c.win.alert("분할비율을 확인하십시오.");
                $c.util.getComponent("ipt_splitRtoContn").focus();
                return false;
            } else {
                if ($c.util.getComponent('dma_saveReq').get('bndMergeObjTpCd')!== "1" && (!Chk_Digit_Point($c.util.getComponent('ipt_splitRtoContn').getValue()) || $c.util.getComponent('ipt_splitRtoContn').getValue()>= 100)) {
                    await $c.win.alert("분할비율을 확인하십시오.");
                    $c.util.getComponent("ipt_splitRtoContn").focus();
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
